function.arguments:
{"path": "wordstats.py", "old_string": "    parser = argparse.ArgumentParser(prog="wordstats", description=__doc__)
    parser.add_argument("files", nargs="*", help="files to read (default: stdin)")
    args = parser.parse_args(argv)

    results = collect(args.files)
    for name, stats in results:
        print(format_row(name, stats))
    if len(results) > 1:
        total = {k: sum(stats[k] for _, stats in results) for k in FIELDS}
        print(format_row("total", total))
    return 0
", "new_string": "    parser = argparse.ArgumentParser(prog="wordstats", description=__doc__)
    parser.add_argument("--format", choices=("table", "json"), default="table")
    parser.add_argument("files", nargs="*", help="files to read (default: stdin)")
    args = parser.parse_args(argv)

    results = collect(args.files)
    if args.format == "json":
        total = {k: sum(stats[k] for _, stats in results) for k in FIELDS}
        payload = {
            "files": [{"name": name, **stats} for name, stats in results],
            "total": total,
        }
        print(json.dumps(payload))
        return 0

    for name, stats in results:
        print(format_row(name, stats))
    if len(results) > 1:
        total = {k: sum(stats[k] for _, stats in results) for k in FIELDS}
        print(format_row("total", total))
    return 0
